items.syntaxPowershell:
$done = @{}
Select-String -Path <json-lines-file> -Pattern '<end-snippet>' | ForEach-Object { $done[($_.Line | ConvertFrom-Json).<key>] = 1 }
Select-String -Path <json-lines-file> -Pattern '<start-snippet>' | ForEach-Object { $_.Line | ConvertFrom-Json } | Where-Object { -not $done.ContainsKey($_.<key>) }

items.powershell:
$done = @{}
Select-String -Path app\checkout-service.log -Pattern '"msg":"server.shutdown"' | ForEach-Object { $done[($_.Line | ConvertFrom-Json).pod] = 1 }
Select-String -Path app\checkout-service.log -Pattern '"msg":"server.start"' | ForEach-Object { $_.Line | ConvertFrom-Json } | Where-Object { -not $done.ContainsKey($_.pod) } | Select-Object ts, pod

items.syntaxPowershell:
# PowerShell uses .NET regex, which backtracks too:
$re = [regex]'<regex>'
<from>..<to> | ForEach-Object { $s = ('<char>' * $_) + '<tail>'; '<format>' -f $_, (Measure-Command { $re.IsMatch($s) }).TotalMilliseconds }

items.powershell:
# PowerShell uses .NET regex, which backtracks too:
$re = [regex]'^(a+)+$'
18..24 | ForEach-Object { $s = ('a' * $_) + '!'; '{0} {1:N0} ms' -f $_, (Measure-Command { $re.IsMatch($s) }).TotalMilliseconds }
